import json
from typing import Any, Dict

def _offers_of(obj):
    # V3.12 多商品：优先取 offers[] 数组；旧单品平面对象包装为 1 品（offer_seq=1）
    if not isinstance(obj, dict):
        return []
    offers = obj.get('offers')
    if isinstance(offers, list):
        out = []
        for i, o in enumerate(offers, start=1):
            if not isinstance(o, dict):
                continue
            e = dict(o)
            e.setdefault('offer_seq', i)
            out.append(e)
        return out
    return [obj]

async def main(args):
    raw = args.params['query_list']
    if not isinstance(raw, str):
        raw = json.dumps(raw, ensure_ascii=False)
    record_json = ''
    offer_id = ''
    req_id = ''
    try:
        arr = json.loads(raw)
        if isinstance(arr, list) and arr:
            first = arr[0]
            if isinstance(first, dict):
                record_json = str(first.get('result_json') or '')
                req_id = str(first.get('req_id') or '')
        elif isinstance(arr, dict):
            record_json = str(arr.get('result_json') or '')
            req_id = str(arr.get('req_id') or '')
    except Exception:
        record_json = ''
    if not record_json:
        record_json = raw
    offers = []
    try:
        inner = json.loads(record_json)
        if isinstance(inner, dict):
            if not req_id:
                req_id = str(inner.get('req_id') or '')
            offers = _offers_of(inner)
            if offers:
                offer_id = str(offers[0].get('offer_id') or offers[0].get('offerId') or '')
    except Exception:
        offers = []
    ret: Output = {
        "record_json": record_json,
        "req_id": req_id,
        "offer_id": offer_id,
        "offers": json.dumps(offers, ensure_ascii=False)
    }
    return ret

import json, random
from typing import Any, Dict

def _str(v):
    return str(v).strip() if v not in (None, '') else ''

def _gen():
    return '900%06d' % random.randint(0, 999999)

def _plan_of(item, req_id):
    # 逐品 plan_json：优先取元素 payload（合并方案 JSON），注入 req_id 供后端提取方案key
    raw = item.get('plan_json') or item.get('payload') or item.get('product_config') or ''
    plan = None
    if isinstance(raw, dict):
        plan = dict(raw)
    elif isinstance(raw, str) and raw.strip():
        try:
            obj = json.loads(raw)
            if isinstance(obj, dict):
                plan = obj
        except Exception:
            plan = None
    if plan is None:
        return ''
    if req_id and not plan.get('req_id'):
        plan['req_id'] = req_id
    return json.dumps(plan, ensure_ascii=False)

async def main(args):
    p = args.params
    req_id = _str(p.get('req_id') or '')
    raw = p.get('offers') or ''
    items = []
    try:
        obj = json.loads(raw) if isinstance(raw, str) else raw
        if isinstance(obj, list):
            items = [dict(o) for o in obj if isinstance(o, dict)]
        elif isinstance(obj, dict):
            if isinstance(obj.get('offers'), list):
                items = [dict(o) for o in obj['offers'] if isinstance(o, dict)]
            elif obj:
                items = [dict(obj)]
    except Exception:
        items = []
    existing = _str(p.get('existing_offer_id') or '')
    out = []
    for i, item in enumerate(items, start=1):
        oid = _str(item.get('offer_id') or item.get('offerId') or '')
        if not oid:
            oid = _str(item.get('similarOfferId') or '')
        if not oid and len(items) == 1:
            oid = existing
        if not (oid.isdigit() and len(oid) == 9):
            oid = _gen()
        seq = int(item.get('offer_seq') or i)
        plan_json = _plan_of(item, req_id)
        out.append({'offer_seq': seq, 'offer_id': oid, 'plan_json': plan_json})
    ret: Output = {
        'offers': json.dumps(out, ensure_ascii=False),
        'offer_id': (out[0]['offer_id'] if out else ''),
    }
    return ret

import json
from typing import Any, Dict

def _load(text):
    # 兼容批量落地出参两种形态：裸 offers[] 数组 或 {offers:[...]} 信封；
    # 均为 {offers:[...]} 便于逐品回显（批量信封顶层不含 product_config）。
    if isinstance(text, list):
        return {'offers': text}
    if isinstance(text, dict):
        return text
    if not isinstance(text, str) or not text.strip():
        return {}
    try:
        obj = json.loads(text)
        if isinstance(obj, list):
            return {'offers': obj}
        return obj if isinstance(obj, dict) else {}
    except Exception:
        try:
            t = text.strip()
            if ':' in t and not t.startswith('{') and not t.startswith('['):
                t = t.split(':', 1)[1].strip()
            obj = json.loads(t)
            if isinstance(obj, list):
                return {'offers': obj}
            return obj if isinstance(obj, dict) else {}
        except Exception:
            return {}

async def main(args):
    p = args.params
    cfg = _load(p.get('group_json') or '')
    raw_status = str(p.get('status') or '')
    # V3.12 多商品：group_json 为批量落地结果 {offers:[{offer_seq,offer_id,status,product_config/group}]}
    elems = None
    if isinstance(cfg, dict) and isinstance(cfg.get('offers'), list):
        elems = [c for c in cfg['offers'] if isinstance(c, dict)]
    lines, failed_all = [], []
    fusion_status = raw_status.upper()
    if elems:
        for i, c in enumerate(elems, start=1):
            seq = int(c.get('offer_seq') or i)
            merged = c.get('group') if isinstance(c.get('group'), dict) else None
            if not merged:
                continue
            members = merged.get('members') or []
            parts = []
            for m in members:
                role = str(m.get('role') or '')
                oid = str(m.get('offer_id') or '')
                if role:
                    parts.append('%s（offer_id %s）' % (role, oid))
                m_status = str(m.get('status') or '').upper()
                if m_status in ('PARTIAL', 'FAIL'):
                    failed_all.append('第%d档 %s=%s' % (seq, role or oid, m_status))
            main_id = str(merged.get('main_offer_id') or c.get('offer_id') or '')
            line = '第%d档融合成员：' % seq
            if main_id:
                line += '主 offer_id %s / ' % main_id
            line += ' / '.join(parts) if parts else ''
            lines.append(line)
        if failed_all and fusion_status == 'SUCCESS':
            fusion_status = 'PARTIAL'
        note = ''
        if fusion_status == 'PARTIAL':
            note = '融合组部分成功（%s）：请按失败明细说明修改意见或回复【重新执行】' % '、'.join(failed_all)
        elif fusion_status == 'FAIL':
            note = '融合组配置失败：请按失败明细说明修改意见或回复【重新执行】'
        ret: Output = {
            'fusion_echo': '\n'.join(lines),
            'fusion_status': fusion_status,
            'fusion_note': note,
        }
        return ret
    # 兼容旧单品：group_json 即单个落地配置
    merged = cfg.get('group') if isinstance(cfg.get('group'), dict) else None
    if not merged:
        ret: Output = {'fusion_echo': '', 'fusion_status': raw_status, 'fusion_note': ''}
        return ret
    members = merged.get('members') or []
    parts = []
    failed = []
    for m in members:
        role = str(m.get('role') or '')
        oid = str(m.get('offer_id') or '')
        if role:
            parts.append('%s（offer_id %s）' % (role, oid))
        m_status = str(m.get('status') or '').upper()
        if m_status in ('PARTIAL', 'FAIL'):
            failed.append('%s=%s' % (role or oid, m_status))
    main_id = str(merged.get('main_offer_id') or cfg.get('offer_id') or '')
    line = '融合成员：'
    if main_id:
        line += '主 offer_id %s / ' % main_id
    line += ' / '.join(parts) if parts else ''
    fusion_status = raw_status.upper()
    if failed and fusion_status == 'SUCCESS':
        fusion_status = 'PARTIAL'
    note = ''
    if fusion_status == 'PARTIAL':
        detail = '、'.join(failed) if failed else '详见失败明细'
        note = '融合组部分成功（%s）：请按失败明细说明修改意见或回复【重新执行】' % detail
    elif fusion_status == 'FAIL':
        note = '融合组配置失败：请按失败明细说明修改意见或回复【重新执行】'
    ret: Output = {
        "fusion_echo": line if parts else '',
        "fusion_status": fusion_status,
        "fusion_note": note,
    }
    return ret

import json
from typing import Any, Dict

def _load(text):
    if isinstance(text, list):
        return {'offers': text}
    if isinstance(text, dict):
        return text
    if not isinstance(text, str) or not text.strip():
        return {}
    try:
        obj = json.loads(text)
        if isinstance(obj, list):
            return {'offers': obj}
        return obj if isinstance(obj, dict) else {}
    except Exception:
        try:
            t = text.strip()
            if ':' in t and not t.startswith('{') and not t.startswith('['):
                t = t.split(':', 1)[1].strip()
            obj = json.loads(t)
            if isinstance(obj, list):
                return {'offers': obj}
            return obj if isinstance(obj, dict) else {}
        except Exception:
            return {}

def _cell(v):
    return str(v) if v not in (None, '') else '—'

def _summary_of(cfg):
    plan = cfg.get('plan_json') if isinstance(cfg.get('plan_json'), dict) else {}
    info = plan.get('optionalInfo') if isinstance(plan.get('optionalInfo'), dict) else {}
    print_c = info.get('printContent') if isinstance(info.get('printContent'), dict) else {}
    gprs = info.get('billGprsCfg') if isinstance(info.get('billGprsCfg'), dict) else {}
    voice = info.get('billVoiceCfg') if isinstance(info.get('billVoiceCfg'), dict) else {}
    base = plan.get('baseInfo') if isinstance(plan.get('baseInfo'), dict) else {}
    in_fee = cfg.get('in_fee') if isinstance(cfg.get('in_fee'), dict) else {}
    offer_name = str(base.get('prodPrcName') or cfg.get('offer_name') or '').strip()
    fee = str(print_c.get('prcMonthFee') or base.get('fixFee') or '').strip()
    gift = str(print_c.get('containResource') or '').strip()
    if not gift:
        parts = []
        if str(gprs.get('theshold') or '').strip():
            parts.append('国内通用流量 %s%s' % (gprs.get('theshold'), gprs.get('unit') or ''))
        if str(voice.get('theshold') or '').strip():
            parts.append('国内通话 %s分钟' % voice.get('theshold'))
        gift = '、'.join(parts)
    out_price = str(print_c.get('chargeStandard') or '').strip()
    if not out_price:
        parts = []
        if str(gprs.get('outChargeMode') or '').strip():
            parts.append('套外流量 %s' % gprs.get('outChargeMode'))
        if str(voice.get('outCharge') or '').strip():
            parts.append('套外语音 %s元/分钟' % voice.get('outCharge'))
        out_price = '、'.join(parts)
    cycle = str(in_fee.get('计费周期') or '').strip()
    carry = '是' if str(gprs.get('carryFlag') or '').strip() in ('是', 'true', 'True', '1') else ''
    lines = ['【配置销售品要点简介】']
    lines.append('- 销售品名称：%s' % _cell(offer_name))
    lines.append('- 套餐档位（月费）：%s' % ((fee + ' 元/月') if fee else '—'))
    lines.append('- 套内资源：%s' % _cell(gift))
    lines.append('- 套外资费：%s' % _cell(out_price))
    if cycle:
        lines.append('- 计费周期：%s' % cycle)
    if carry:
        lines.append('- 流量结转：可结转至次月')
    lines.append('- 订购规则：%s' % _cell(cfg.get('order_rule')))
    lines.append('- 退订规则：%s' % _cell(cfg.get('cancel_rule')))
    return '\n'.join(lines)

async def main(args):
    p = args.params
    cfg = _load(p.get('product_config') or '')
    req_id = str(p.get('req_id') or '')
    # V3.12 多商品：product_config 为节点103出参 offers[]（含逐品 product_config）；
    # 组装 config_json={req_id, offers:[...]} 信封供下游 result_json 落库（下游按 offers[] 键提取）。
    if isinstance(cfg, dict) and isinstance(cfg.get('offers'), list):
        blocks, offers_out, cfg_offers = [], [], []
        for i, c in enumerate(cfg['offers'], start=1):
            if not isinstance(c, dict):
                continue
            seq = int(c.get('offer_seq') or i)
            inner = c.get('product_config')
            if isinstance(inner, str):
                inner = _load(inner) or None
            elif not isinstance(inner, dict):
                inner = None
            if inner is None:
                inner = c
            text = _summary_of(inner)
            blocks.append('第%d档：\n%s' % (seq, text))
            offers_out.append({'offer_seq': seq, 'config_summary': text})
            cfg_offers.append(c)
        config_json = json.dumps({'req_id': req_id, 'offers': cfg_offers}, ensure_ascii=False)
        ret: Output = {
            'config_summary': '\n\n'.join(blocks),
            'offers': json.dumps(offers_out, ensure_ascii=False),
            'config_json': config_json,
        }
        return ret
    if not cfg:
        ret: Output = {'config_summary': '', 'offers': '[]', 'config_json': json.dumps({'req_id': req_id, 'offers': []}, ensure_ascii=False)}
        return ret
    one_sum = _summary_of(cfg)
    ret: Output = {'config_summary': one_sum, 'offers': json.dumps([{'offer_seq': 1, 'config_summary': one_sum}], ensure_ascii=False), 'config_json': json.dumps({'req_id': req_id, 'offers': [cfg]}, ensure_ascii=False)}
    return ret

